records = []
for state, family, authority, basis, permit, url, archive, action, status in defs:
    if state == "Ohio" and family in {"County Engineer", "Municipality", "Township"}:
        d = spans[(spans.state == "OH") & (spans.boundary_name.str.upper() == authority.replace("City of ", "").replace(" Township", "").upper())]
        if family == "County Engineer":
            name = authority.replace(" County Engineer", "").upper()
            d = spans[(spans.state == "OH") & (spans.boundary_type == "county") & (spans.boundary_name.str.upper() == name)]
        elif family == "Municipality":
            name = authority.replace("City of ", "").upper()
            d = spans[(spans.state == "OH") & (spans.boundary_type == "place") & (spans.boundary_name.str.upper() == name)]
        else:
            name = authority.replace(" Township", "").upper()
            d = spans[(spans.state == "OH") & (spans.boundary_type == "township") & (spans.boundary_name.str.upper() == name)]
    elif state == "Illinois" and family in {"County DOT", "Municipality", "Township/Road District"}:
        typ = {"County DOT":"county", "Municipality":"place", "Township/Road District":"township"}[family]
        name = authority.replace(" County DoTH", "").replace(" County DOT", "").replace(" Village", "").replace(" Township", "").upper()
        d = spans[(spans.state == "IL") & (spans.boundary_type == typ) & (spans.boundary_name.str.upper() == name)]
    else:
        d = pd.DataFrame()
    features = "; ".join(sorted(d.feature_id.unique())) if len(d) else "Route/facility candidate; station-specific overlap not established"
    length = round(float(d.centerline_length_ft.sum()), 1) if len(d) else ""
    records.append({"state_scope":state,"authority_family":family,"candidate_ahj_or_owner":authority,"route_basis":basis,"feature_ids_from_boundary_or_special_screen":features,"approx_length_ft_boundary_screen":length,"candidate_permit_or_approval":permit,"official_process_source":url,"row_record_archive_or_map_source":archive,"next_vendor_action":action,"evidence_status":status})

pd.DataFrame(records).to_csv(ROOT / "ahj_and_row_record_register.csv", index=False)
print(f"Wrote {len(records)} AHJ/record-source rows")
